import '../../core/models/talent.dart';\nimport '../../core/models/opportunity.dart';\nimport 'talent_discovery_service.dart';\n\nclass AurenAgentStep {\n  final String agent;\n  final String title;\n  final String instruction;\n  const AurenAgentStep({required this.agent, required this.title, required this.instruction});\n}\n\nclass AurenTalentAgentOrchestrator {\n  const AurenTalentAgentOrchestrator();\n\n  List<AurenAgentStep> buildWorkflow({\n    required AurenTalent talent,\n    required AurenOpportunity opportunity,\n    required AurenTalentMatch match,\n  }) {\n    final skills = talent.skills.join(', ');\n    final missing = match.missingSkills.join(', ');\n    return [\n      AurenAgentStep(agent: 'Talent Discovery Agent', title: 'فهم الفرصة', instruction: 'حلل الفرصة مقابل مهارات الموهبة: ' + skills + '. حدد المتطلبات الأساسية.'),\n      AurenAgentStep(agent: 'Opportunity Match Agent', title: 'تفسير المطابقة', instruction: 'المطابقة المحسوبة ' + match.score.toString() + '%. المتطابقة: ' + match.matchedSkills.join(', ') + '. الفجوات: ' + missing + '.'),\n      AurenAgentStep(agent: 'Skill Coach Agent', title: 'سد الفجوة', instruction: 'حوّل المهارات الناقصة إلى خطة تعلم وممارسة مرتبطة بالفرصة.'),\n      AurenAgentStep(agent: 'Career Agent', title: 'خطة التقدم', instruction: 'ابنِ خطوات عملية للتقديم والتطور المهني، وحدد الأولوية.'),\n      AurenAgentStep(agent: 'Portfolio Agent', title: 'تجهيز الملف', instruction: 'حدد الأعمال والأدلة التي ينبغي إبرازها في ملف الموهبة لهذه الفرصة.'),\n      AurenAgentStep(agent: 'Negotiation Agent', title: 'الاستعداد للتفاوض', instruction: 'جهز أسئلة ونقاط تفاوض ومعلومات يجب التحقق منها قبل أي اتفاق.'),\n    ];\n  }\n}